const $=s=>document.querySelector(s),canvas=$('#scene'),ctx=canvas.getContext('2d'),defaults={nose:45,wing:55,trim:3,body:12,opening:15,dihedral:0};
let params={...defaults},history=[],undo=[],redo=[],mode='edit',oblique=true,comparison=true,current=null,previous=null,animation=0,progress=0,w=0,h=0,handles=[],drag=null,storeOK=true;
try{const saved=JSON.parse(localStorage.getItem('paperlab-v1')||'null');if(saved){for(const k of Object.keys(defaults))if(Number.isFinite(saved.params?.[k]))params[k]=Math.min(k==='trim'?12:k==='body'?24:k==='opening'?30:k==='dihedral'?35:100,Math.max(k==='trim'?-4:k==='body'?4:k==='dihedral'?-15:0,saved.params[k]));if(saved.schema!==2&&params.opening===0)params.opening=15;params.cuts=validCuts(saved.params?.cuts);history=Array.isArray(saved.history)?saved.history.filter(r=>r.model===1&&r.params&&Array.isArray(r.points)&&Number.isFinite(r.distance)).slice(0,10):[]}}catch{}
function persist(){try{localStorage.setItem('paperlab-v1',JSON.stringify({schema:2,params,history}));storeOK=true}catch{storeOK=false}$('#saveState').textContent=storeOK?'● 已保存到本设备':'○ 本次使用中保留'}
function toast(t){$('#toast').textContent=t;$('#toast').classList.add('show');setTimeout(()=>$('#toast').classList.remove('show'),2200)}
function remember(){undo.push({...params});if(undo.length>30)undo.shift();redo=[]}
function sync(){for(const k of Object.keys(defaults)){$('#'+k).value=params[k];$('#'+k+'Val').textContent=['trim','dihedral','opening'].includes(k)?(params[k]>0?'+':'')+params[k]+'°':params[k]+'%'}const mesh=buildPlaneMesh(params);$('#rootGap').textContent='翼根间距约为机长的 '+(mesh.rootGap/mesh.length*100).toFixed(1)+'% · 随折角联动';$('#cutCount').textContent=(params.cuts?.length||0)+' 条已确认剪线';$('#undo').disabled=!undo.length;$('#redo').disabled=!redo.length;draw()}
for(const k of Object.keys(defaults)){
 const input=$('#'+k);let editing=false;
 // Record the first actual change, so every input method supports undo and no-ops keep redo.
 input.addEventListener('pointerdown',()=>{editing=false});
 input.addEventListener('keydown',()=>{editing=false});
 input.addEventListener('input',e=>{const value=+e.target.value;if(value===params[k])return;if(!editing)remember();editing=true;params[k]=value;sync()});
 input.addEventListener('change',()=>{editing=false;persist()});
}
$('#undo').onclick=()=>{if(!undo.length)return;redo.push({...params});params=undo.pop();sync();persist()};$('#redo').onclick=()=>{if(!redo.length)return;undo.push({...params});params=redo.pop();sync();persist()};$('#reset').onclick=()=>{if(confirm('恢复默认飞机？已有试飞记录会保留。')){remember();params={...defaults};sync();persist()}};
function poly(pts,fill,stroke='#9679b2'){ctx.beginPath();pts.forEach((p,i)=>i?ctx.lineTo(...p):ctx.moveTo(...p));ctx.closePath();ctx.fillStyle=fill;ctx.fill();ctx.strokeStyle=stroke;ctx.lineWidth=1;ctx.stroke()}
function plane(cx,cy,size,p,angle=0,editor=false){ctx.save();ctx.translate(cx,cy);ctx.rotate(angle);let L=size*(1.08-p.nose*.002),B=size*(.37+p.wing*.003);const nose=[L*.62,0],tail=[-L*.48,0],tip1=[-L*.22,-B],tip2=[-L*.22,B],fold1=[-L*.35,-B*.18],fold2=[-L*.35,B*.18];
 if(editor&&oblique)ctx.transform(1,-.3,.33,.62,0,0);
 ctx.save();ctx.translate(8,20);ctx.globalAlpha=.09;ctx.filter='blur(12px)';poly([nose,tip1,tail,tip2],'#6736a8','transparent');ctx.restore();
 poly([nose,tip1,fold1],'#fffae9');poly([nose,fold1,tail],'#decaed');poly([nose,tail,fold2],'#bfa2d9');poly([nose,fold2,tip2],'#fffcef');
 const bend=p.trim*1.5;poly([[tip2[0],tip2[1]],[fold2[0],fold2[1]],[-L*.36,fold2[1]-bend],[-L*.28,tip2[1]-bend]],'#f7e2bd');
 ctx.setLineDash([4,4]);ctx.strokeStyle='#9679b2';ctx.beginPath();ctx.moveTo(...tail);ctx.lineTo(...nose);ctx.stroke();ctx.setLineDash([]);
 if(editor){handles=[];for(const [name,pt]of [['nose',nose],['wing',tip2]]){let matrix=ctx.getTransform();handles.push({name,x:matrix.a*pt[0]+matrix.c*pt[1]+matrix.e,y:matrix.b*pt[0]+matrix.d*pt[1]+matrix.f});ctx.beginPath();ctx.arc(...pt,8,0,Math.PI*2);ctx.fillStyle='#fffae9';ctx.fill();ctx.strokeStyle='#6736a8';ctx.lineWidth=2;ctx.stroke();ctx.beginPath();ctx.arc(...pt,2.5,0,Math.PI*2);ctx.fillStyle='#6736a8';ctx.fill()}}
 ctx.restore()}
function resize(){const r=canvas.getBoundingClientRect();w=r.width;h=r.height;canvas.width=w*devicePixelRatio;canvas.height=h*devicePixelRatio;ctx.setTransform(devicePixelRatio,0,0,devicePixelRatio,0,0);draw()}
new ResizeObserver(resize).observe(canvas);
function draw(){ctx.clearRect(0,0,w,h);if(mode==='edit'){drawPlane3D(ctx,w,h,params);return}if(!current)return;
 const maxX=Math.max(current.distance,previous?.distance||0,12)*1.12,scale=Math.min((w-70)/maxX,(h-140)/(Math.max(current.height,previous?.height||0,3)+1)),ground=h-58,origin=35;const point=a=>[origin+a.x*scale,ground-a.y*scale];
 ctx.fillStyle='#f5ead4';ctx.fillRect(0,ground,w,h-ground);ctx.strokeStyle='#a18bb7';ctx.beginPath();ctx.moveTo(0,ground);ctx.lineTo(w,ground);ctx.stroke();ctx.font='9px monospace';ctx.fillStyle='#6d5a79';for(let m=0;m<maxX;m+=maxX>45?10:5){let x=origin+m*scale;ctx.fillText(m+' m',x,ground+20);ctx.beginPath();ctx.moveTo(x,ground);ctx.lineTo(x,ground+5);ctx.stroke()}
 function trail(points,color,dashed){ctx.strokeStyle=color;ctx.lineWidth=2;ctx.setLineDash(dashed?[4,5]:[]);ctx.beginPath();points.forEach((a,i)=>{const p=point(a);i?ctx.lineTo(...p):ctx.moveTo(...p)});ctx.stroke();ctx.setLineDash([])}
 if(previous&&comparison)trail(previous.points,'#8e70b2',true);const count=Math.max(1,Math.floor(progress*(current.points.length-1))+1),pts=current.points.slice(0,count);trail(pts,'#006b57',false);let a=pts.at(-1),[x,y]=point(a);plane(x,y,27,params,-a.theta);$('#live strong').innerHTML=Math.max(0,a.x).toFixed(1)+' <small>m</small>';
 if(mode==='result'){ctx.beginPath();ctx.arc(x,ground,5,0,Math.PI*2);ctx.fillStyle='#ff773e';ctx.fill()}
}
let orbitDrag=null;let viewIndex=0,editViewLabel='3D / ORBIT VIEW';
function setEditViewLabel(label){editViewLabel=label;if(mode==='edit')$('#modeLabel').textContent=label}
const presetViews=[[-.62,.57,'3D / ORBIT VIEW'],[0,1.48,'TOP VIEW'],[0,0,'SIDE VIEW'],[Math.PI/2,0,'FRONT VIEW']];
$('#view').onclick=()=>{viewIndex=(viewIndex+1)%presetViews.length;const v=presetViews[viewIndex];orbit.yaw=v[0];orbit.pitch=v[1];setEditViewLabel(v[2]);draw()};
$('#homeView').onclick=()=>{orbit.yaw=-.62;orbit.pitch=.57;orbit.zoom=1;viewIndex=0;setEditViewLabel('3D / ORBIT VIEW');draw()};
$('#zoomIn').onclick=()=>{orbit.zoom=Math.min(1.5,orbit.zoom+.1);draw()};$('#zoomOut').onclick=()=>{orbit.zoom=Math.max(.65,orbit.zoom-.1);draw()};
$('#compare').onclick=()=>{comparison=!comparison;$('#compare').setAttribute('aria-pressed',comparison);$('#compare').style.opacity=comparison?1:.5;draw()};
canvas.onpointerdown=e=>{if(mode!=='edit')return;orbitDrag={x:e.clientX,y:e.clientY};canvas.setPointerCapture(e.pointerId);canvas.classList.add('rotating')};
canvas.onpointermove=e=>{if(!orbitDrag||mode!=='edit')return;orbit.yaw+=(e.clientX-orbitDrag.x)*.009;orbit.pitch=Math.max(-1.48,Math.min(1.48,orbit.pitch+(e.clientY-orbitDrag.y)*.009));orbitDrag={x:e.clientX,y:e.clientY};setEditViewLabel('3D / ORBIT VIEW');draw()};
canvas.onpointerup=canvas.onpointercancel=()=>{orbitDrag=null;canvas.classList.remove('rotating')};
canvas.addEventListener('wheel',e=>{if(mode!=='edit')return;e.preventDefault();orbit.zoom=Math.max(.65,Math.min(1.5,orbit.zoom-e.deltaY*.001));draw()},{passive:false});
canvas.addEventListener('keydown',e=>{if(mode!=='edit')return;let used=true;if(e.key==='ArrowLeft')orbit.yaw-=.12;else if(e.key==='ArrowRight')orbit.yaw+=.12;else if(e.key==='ArrowUp')orbit.pitch=Math.min(1.48,orbit.pitch+.12);else if(e.key==='ArrowDown')orbit.pitch=Math.max(-1.48,orbit.pitch-.12);else used=false;if(used){e.preventDefault();setEditViewLabel('3D / ORBIT VIEW');draw()}});
function setMode(next){mode=next;$('#modeLabel').textContent=next==='edit'?editViewLabel:'SIDE / FLIGHT PATH';$('#controls').hidden=next!=='edit';$('#result').hidden=next!=='result';$('#live').hidden=next==='edit';$('#view').hidden=next!=='edit';for(const id of ['homeView','zoomIn','zoomOut'])$('#'+id).hidden=next!=='edit';canvas.style.cursor=next==='edit'?'grab':'default';$('#compare').style.display=next!=='edit'&&previous?'block':'none';$('#again').hidden=next!=='result';$('#stageLabel').innerHTML=next==='edit'?'设计工作台 <small>DESIGN STUDIO</small>':'试飞场 <small>FLIGHT TEST</small>';$('#panelKicker').textContent=next==='edit'?'MAKE IT YOURS':next==='flight'?'LET IT FLY':'ONE MORE DISCOVERY';$('#panelTitle').textContent=next==='edit'?'调整你的飞机':next==='flight'?'让折痕说话。':'这次，飞得如何？';$('#panelSub').textContent=next==='edit'?'轻轻改动，看看会发生什么。':next==='flight'?'相同的起点，不同的可能。':'保留这次发现，继续你的实验。';$('#launch').innerHTML=next==='edit'?'开始试飞 <span>↗</span>':next==='flight'?'结束测试，返回编辑 <span>↶</span>':'继续修改飞机 <span>↶</span>';$('#hint').textContent=next==='edit'?'按住拖动旋转 · 滚轮缩放 · 右侧调整折角':next==='flight'?'8.2 m/s 水平初速度 · 1.65 m 投掷高度':(previous?'实线是本次飞行，虚线是上一次的你':'第一条轨迹，下一次飞行的起点');for(let i=1;i<4;i++)$('#step'+i).classList.toggle('active',i===(next==='edit'?1:next==='flight'?2:3));draw()}
function launch(){previous=history[0]||null;current=simulate(params);if(!current){toast('模拟未完成，请小幅调整飞机后重试');return}progress=0;setMode('flight');const start=performance.now(),duration=Math.min(12000,Math.max(4500,current.time*1000));function tick(now){if(mode!=='flight')return;progress=Math.min(1,(now-start)/duration);draw();if(progress<1)animation=requestAnimationFrame(tick);else finish()}animation=requestAnimationFrame(tick)}
function finish(){history.unshift({...current,id:Date.now()});history=history.slice(0,10);persist();$('#distance').textContent=current.distance.toFixed(1);$('#duration').textContent=current.time.toFixed(1)+' s';$('#height').textContent=current.height.toFixed(1)+' m';const diff=previous?Number(current.distance.toFixed(1))-Number(previous.distance.toFixed(1)):null;$('#delta').textContent=diff===null?'你的第一条飞行记录':Math.abs(diff)<.05?'与上次距离相同':(diff>0?'↑ 比上次远 ':'↓ 比上次近 ')+Math.abs(diff).toFixed(1)+' m';$('#feedback').textContent=current.stalls>12?'本次轨迹出现较大迎角。试着减小翼尾上翘，再观察飞行是否更平顺。':current.height>3?'飞机经历了明显爬升。试着小幅修改翼尾，对比滞空与距离的变化。':'完成了一次滑翔。试着只调整机翼比例，让下一次轨迹告诉你差别。';setMode('result');renderHistory()}
$('#launch').onclick=()=>{if(mode==='edit')launch();else{cancelAnimationFrame(animation);setMode('edit');sync()}};$('#again').onclick=launch;
function renderHistory(){const el=$('#records');el.replaceChildren();$('#count').textContent=history.length+' 次近期试飞';if(!history.length){el.innerHTML='<div class="empty">还没有飞行记录。你的第一次起飞，就从这里开始。 ↗</div>';return}history.forEach((r,i)=>{let b=document.createElement('button');b.className='record';b.innerHTML='<div class="top"><span>'+ (i===0?'最近一次':'历史试飞')+'</span><span>↗ 恢复设计</span></div><strong>'+r.distance.toFixed(1)+' <small>m</small></strong><small>'+r.time.toFixed(1)+' 秒滞空</small><p>机头 '+Number(r.params.nose)+' · 翼面 '+Number(r.params.wing)+' · 翼尾 '+Number(r.params.trim)+'° · 机身 '+Number(r.params.body??12)+'%<br>张开 '+Number(r.params.opening??0)+'° · 机翼 '+Number(r.params.dihedral??0)+'°</p>';b.onclick=()=>{cancelAnimationFrame(animation);remember();params={...defaults,...r.params,cuts:validCuts(r.params.cuts)};setMode('edit');sync();persist();toast('已恢复这次飞机，可以继续修改')};el.appendChild(b)})}
renderHistory();sync();persist();setMode('edit');
$('#bodySide').onclick=()=>{orbit.yaw=0;orbit.pitch=0;orbit.zoom=1;viewIndex=2;setEditViewLabel('SIDE VIEW / BODY HEIGHT');draw()};

